# 燃烧三条件判断
fuel = True      # 有可燃物（蜡烛）
oxygen = True    # 有氧气
hot = True       # 温度达到着火点

if fuel:
    if oxygen:
        if hot:
            say("三个条件齐了——燃烧！")
        else:
            say("温度不够，点不着")
    else:
        say("没氧气，熄灭！")

# 消防实验：盖杯盖（隔绝氧气）
oxygen = False
if oxygen == False:
    say("盖上杯盖 -> 氧气耗尽 -> 火灭了！")
